interface Produto {
  id: number;
  nome: string;
  preco: number;
  emStock: boolean;
}

type ChaveProduto = keyof Produto;
// ChaveProduto = "id" | "nome" | "preco" | "emStock"

const chave: ChaveProduto = "preco";
console.log(chave); // preco

// @ts-expect-error "desconto" não é uma propriedade de Produto, logo não pertence a keyof Produto
const inexistente: ChaveProduto = "desconto";

const todasAsChaves: ChaveProduto[] = ["id", "nome", "preco", "emStock"];
console.log(todasAsChaves.length); // 4

function existe(produto: Produto, k: keyof Produto): boolean {
  return produto[k] !== undefined;
}

console.log(existe({ id: 1, nome: "cabo", preco: 4.5, emStock: true }, "nome")); // true

interface Contagens {
  [chave: string]: number;
}
type ChavesContagens = keyof Contagens; // string | number

const porTexto: ChavesContagens = "total";
const porIndice: ChavesContagens = 3;
console.log(porTexto, porIndice); // total 3

interface Linhas {
  [indice: number]: string;
}
type ChavesLinhas = keyof Linhas; // number

// @ts-expect-error uma index signature numérica só aceita chaves numéricas
const textual: ChavesLinhas = "0";

type Vazio = {};
type ChavesVazio = keyof Vazio; // never

// @ts-expect-error never não admite valor nenhum, nem sequer uma string
const impossivel: ChavesVazio = "nome";

type Forma = { lado: number } | { raio: number };
type ChavesForma = keyof Forma; // never, porque não há chave comum aos dois membros

console.log(typeof porTexto); // string

const PORTA = 8080;

const definicoes = {
  porta: PORTA,
  anfitriao: "localhost",
  tentativas: 3,
  verboso: false,
};

type Definicoes = typeof definicoes;
// { porta: number; anfitriao: string; tentativas: number; verboso: boolean }

const emTeste: Definicoes = {
  porta: 9090,
  anfitriao: "127.0.0.1",
  tentativas: 1,
  verboso: true,
};
console.log(emTeste.porta); // 9090

function formatar(valor: number, casas: number): string {
  return valor.toFixed(casas);
}

type Formatador = typeof formatar; // (valor: number, casas: number) => string

const comMoeda: Formatador = (valor, casas) => `${valor.toFixed(casas)} EUR`;
console.log(comMoeda(3.14159, 2)); // 3.14 EUR

// O typeof de valores continua a existir e devolve uma string em tempo de execução
console.log(typeof PORTA); // number

// @ts-expect-error o typeof de tipo aplica-se a valores; Definicoes já é um tipo
type Duplicado = typeof Definicoes;

const ESTADOS = {
  pendente: "PENDENTE",
  emCurso: "EM_CURSO",
  concluido: "CONCLUIDO",
};

type FormaDeEstados = typeof ESTADOS;
// { pendente: string; emCurso: string; concluido: string }

type Estado = keyof typeof ESTADOS;
// "pendente" | "emCurso" | "concluido"

function descrever(estado: Estado): string {
  return `código interno: ${ESTADOS[estado]}`;
}

console.log(descrever("emCurso")); // código interno: EM_CURSO
console.log(descrever("pendente")); // código interno: PENDENTE

// @ts-expect-error "cancelado" não é chave de ESTADOS, logo não pertence a Estado
const fora: Estado = "cancelado";

const todos: Estado[] = Object.keys(ESTADOS) as Estado[];
console.log(todos.join(", ")); // pendente, emCurso, concluido

const soParaVerificar: FormaDeEstados = ESTADOS;
console.log(soParaVerificar.concluido); // CONCLUIDO

interface Encomenda {
  id: number;
  cliente: { nome: string; nif: string };
  total: number;
  pago: boolean;
}

type Id = Encomenda["id"]; // number
type Cliente = Encomenda["cliente"]; // { nome: string; nif: string }
type Nif = Encomenda["cliente"]["nif"]; // string
type TotalOuPago = Encomenda["total" | "pago"]; // number | boolean
type ValoresDeEncomenda = Encomenda[keyof Encomenda];
// number | boolean | { nome: string; nif: string }

const id: Id = 17;
const cliente: Cliente = { nome: "Rita", nif: "123456789" };
const nif: Nif = cliente.nif;
const totalOuPago: TotalOuPago = true;
console.log(id, nif, totalOuPago); // 17 123456789 true

const valor: ValoresDeEncomenda = 42;
console.log(valor); // 42

// @ts-expect-error o acesso indexado usa parênteses retos e um tipo, não a notação com ponto
type Errado = Encomenda.total;

type Linha = { produto: string; quantidade: number };
interface Fatura {
  linhas: Linha[];
  data: string;
}

type UmaLinha = Fatura["linhas"][number]; // Linha
const primeira: UmaLinha = { produto: "cabo HDMI", quantidade: 2 };
console.log(primeira.quantidade); // 2

type Coordenada = [number, number, string];
type PartesDaCoordenada = Coordenada[number]; // number | string
const parte: PartesDaCoordenada = "norte";
console.log(parte); // norte

const semAsConst = { ambiente: "producao", porta: 443 };
// { ambiente: string; porta: number }
semAsConst.ambiente = "teste";
console.log(semAsConst.ambiente); // teste

const config = { ambiente: "producao", porta: 443 } as const;
// { readonly ambiente: "producao"; readonly porta: 443 }
console.log(config.porta); // 443

// @ts-expect-error as const tornou todas as propriedades apenas de leitura
config.ambiente = "teste";

const CORES = ["vermelho", "verde", "azul"] as const;
// readonly ["vermelho", "verde", "azul"]
console.log(CORES.length); // 3

type Cor = (typeof CORES)[number]; // "vermelho" | "verde" | "azul"

const preferida: Cor = "verde";
console.log(preferida); // verde

function pintar(cor: Cor): string {
  return `a pintar de ${cor}`;
}
console.log(pintar(CORES[2])); // a pintar de azul

// @ts-expect-error "roxo" não está no array CORES, logo não pertence a Cor
const ausente: Cor = "roxo";

// @ts-expect-error uma tupla apenas de leitura não tem push
CORES.push("preto");

function obter<T, K extends keyof T>(objeto: T, chave: K): T[K] {
  return objeto[chave];
}

const CONFIG = {
  ambiente: "producao",
  porta: 443,
  tls: true,
  regioes: ["pt", "es", "fr"],
} as const;

type Config = typeof CONFIG;
type ChaveConfig = keyof Config; // "ambiente" | "porta" | "tls" | "regioes"
type Regiao = Config["regioes"][number]; // "pt" | "es" | "fr"
type ValorConfig = Config[ChaveConfig];

const porta = obter(CONFIG, "porta");
console.log(porta); // 443

const ambiente: Config["ambiente"] = "producao";
console.log(ambiente); // producao

const regiao: Regiao = "es";
console.log(regiao); // es

const qualquerValor: ValorConfig = true;
console.log(qualquerValor); // true

// @ts-expect-error "idioma" não é chave de CONFIG, logo não satisfaz K extends keyof Config
obter(CONFIG, "idioma");

function descrever<K extends ChaveConfig>(chave: K): string {
  return `${chave} = ${String(CONFIG[chave])}`;
}
console.log(descrever("tls")); // tls = true
console.log(descrever("regioes")); // regioes = pt,es,fr

