const IDIOMAS = {
  pt: "Português",
  en: "Inglês",
  fr: "Francês",
};

type CodigoIdioma = keyof typeof IDIOMAS; // "pt" | "en" | "fr"
type NomeIdioma = (typeof IDIOMAS)[CodigoIdioma]; // string

function nomeDoIdioma(codigo: CodigoIdioma): NomeIdioma {
  return IDIOMAS[codigo];
}

console.log(nomeDoIdioma("pt")); // Português
console.log(nomeDoIdioma("fr")); // Francês

// @ts-expect-error "de" não é chave de IDIOMAS, logo não pertence a CodigoIdioma
nomeDoIdioma("de");

const NIVEIS = ["debug", "info", "aviso", "erro"] as const;

type Nivel = (typeof NIVEIS)[number]; // "debug" | "info" | "aviso" | "erro"

function registar(nivel: Nivel, mensagem: string): string {
  return `[${nivel.toUpperCase()}] ${mensagem}`;
}

console.log(registar("aviso", "disco quase cheio")); // [AVISO] disco quase cheio
console.log(registar(NIVEIS[0], "a iniciar")); // [DEBUG] a iniciar

// @ts-expect-error "fatal" não está em NIVEIS
registar("fatal", "tudo em baixo");

// @ts-expect-error NIVEIS é uma tupla apenas de leitura
NIVEIS[0] = "verbose";

interface Empresa {
  nome: string;
  morada: {
    rua: string;
    codigoPostal: string;
    pais: string;
  };
  trabalhadores: { nome: string; departamento: string }[];
  ativa: boolean;
}

type Morada = Empresa["morada"];
type Pais = Empresa["morada"]["pais"]; // string
type Trabalhador = Empresa["trabalhadores"][number];
type Departamento = Trabalhador["departamento"]; // string
type ValorDeEmpresa = Empresa[keyof Empresa];
// string | boolean | { rua: string; codigoPostal: string; pais: string } | { nome: string; departamento: string }[]

const morada: Morada = {
  rua: "Rua das Flores, 10",
  codigoPostal: "4700-000",
  pais: "Portugal",
};

const pais: Pais = morada.pais;
const trabalhador: Trabalhador = { nome: "Sofia", departamento: "Engenharia" };
const departamento: Departamento = trabalhador.departamento;

console.log(pais); // Portugal
console.log(departamento); // Engenharia

const valor: ValorDeEmpresa = true;
console.log(valor); // true

// @ts-expect-error "cidade" não é propriedade de Empresa["morada"]
type Cidade = Empresa["morada"]["cidade"];

function obterEncaixado<T, K1 extends keyof T, K2 extends keyof T[K1]>(
  objeto: T,
  primeira: K1,
  segunda: K2,
): T[K1][K2] {
  return objeto[primeira][segunda];
}

const definicoes = {
  janela: { largura: 1280, altura: 720, titulo: "Editor" },
  utilizador: { nome: "Inês", administrador: true },
};

const largura = obterEncaixado(definicoes, "janela", "largura");
const nome = obterEncaixado(definicoes, "utilizador", "nome");
const admin = obterEncaixado(definicoes, "utilizador", "administrador");

console.log(largura); // 1280
console.log(nome.toUpperCase()); // INÊS
console.log(admin); // true

const verificaLargura: number = largura;
const verificaNome: string = nome;
console.log(verificaLargura + verificaNome.length); // 1284

// @ts-expect-error "profundidade" não é chave de definicoes["janela"]
obterEncaixado(definicoes, "janela", "profundidade");

try {
  // @ts-expect-error "rede" não é chave de definicoes
  obterEncaixado(definicoes, "rede", "porta");
} catch {
  console.log("não existe janela rede nas definições"); // não existe janela rede nas definições
}
